(()=>{const items=[...document.querySelectorAll(".type-drift")],mq=matchMedia("(prefers-reduced-motion:reduce)");let pending=false;function update(){pending=false;const off=mq.matches||document.documentElement.classList.contains("motion-paused");items.forEach((e,i)=>{const r=e.getBoundingClientRect();const shift=off?0:Math.max(-16,Math.min(16,(r.top-innerHeight*.4)*.025))*(i%2?-1:1);e.style.setProperty("--type-shift",shift+"px")})}function schedule(){if(!pending){pending=true;requestAnimationFrame(update)}}addEventListener("scroll",schedule,{passive:true});addEventListener("site-motion-change",schedule);mq.addEventListener("change",schedule);schedule()})();
